class UI {
    static showToast(message, type = 'info', duration = 4000) {
        const container = document.querySelector('.toast-container');
        if (!container) {
            const div = document.createElement('div');
            div.className = 'toast-container';
            document.body.appendChild(div);
        }

        const icons = {
            success: '✅',
            error: '❌',
            warning: '⚠️',
            info: 'ℹ️',
        };

        const toast = document.createElement('div');
        toast.className = `toast ${type}`;
        toast.innerHTML = `
            <span class="toast-icon">${icons[type] || 'ℹ️'}</span>
            <span class="toast-message">${message}</span>
            <button class="toast-close" onclick="this.parentElement.remove()">✕</button>
        `;

        document.querySelector('.toast-container').appendChild(toast);

        setTimeout(() => {
            if (toast.parentElement) {
                toast.style.animation = 'none';
                toast.style.opacity = '0';
                toast.style.transform = 'translateX(100%)';
                setTimeout(() => toast.remove(), 300);
            }
        }, duration);
    }

    static showModal(html, options = {}) {
        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay active';
        overlay.innerHTML = `
            <div class="modal">
                <div class="modal-header">
                    <h3 class="modal-title">${options.title || 'Modal'}</h3>
                    <button class="modal-close" onclick="this.closest('.modal-overlay').remove()">✕</button>
                </div>
                <div class="modal-body">
                    ${html}
                </div>
                ${options.footer ? `<div class="modal-footer">${options.footer}</div>` : ''}
            </div>
        `;

        document.body.appendChild(overlay);

        // Close on overlay click
        overlay.addEventListener('click', (e) => {
            if (e.target === overlay) {
                overlay.remove();
            }
        });

        return overlay;
    }

    static showConfirm(message, title = 'Confirm') {
        return new Promise((resolve) => {
            const overlay = document.createElement('div');
            overlay.className = 'modal-overlay active';
            overlay.innerHTML = `
                <div class="modal">
                    <div class="modal-header">
                        <h3 class="modal-title">${title}</h3>
                        <button class="modal-close" onclick="this.closest('.modal-overlay').remove(); resolve(false)">✕</button>
                    </div>
                    <div class="modal-body">
                        <p style="color: var(--text-secondary);">${message}</p>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" onclick="this.closest('.modal-overlay').remove(); resolve(false)">Cancel</button>
                        <button class="btn btn-danger" onclick="this.closest('.modal-overlay').remove(); resolve(true)">Confirm</button>
                    </div>
                </div>
            `;

            document.body.appendChild(overlay);

            overlay.addEventListener('click', (e) => {
                if (e.target === overlay) {
                    overlay.remove();
                    resolve(false);
                }
            });
        });
    }

    static showLoading(container) {
        container.innerHTML = `
            <div class="loading-overlay">
                <div class="spinner spinner-lg"></div>
                <p>Loading...</p>
            </div>
        `;
    }

    static showEmpty(container, { icon = '📦', title = 'Nothing here', message = 'No items to display.', action = '' } = {}) {
        container.innerHTML = `
            <div class="empty-state">
                <div class="empty-state-icon">${icon}</div>
                <div class="empty-state-title">${title}</div>
                <div class="empty-state-text">${message}</div>
                ${action}
            </div>
        `;
    }

    static showError(container, message = 'An error occurred') {
        container.innerHTML = `
            <div class="empty-state">
                <div class="empty-state-icon">❌</div>
                <div class="empty-state-title">Error</div>
                <div class="empty-state-text">${message}</div>
                <button class="btn btn-primary" onclick="location.reload()">Try Again</button>
            </div>
        `;
    }

    static formatDate(dateStr) {
        const date = new Date(dateStr);
        const now = new Date();
        const diff = now - date;

        if (diff < 60000) return 'Just now';
        if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
        if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
        if (diff < 604800000) return `${Math.floor(diff / 86400000)}d ago`;

        return date.toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
            year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined,
        });
    }

    static formatNumber(num) {
        if (!num) return '0';
        if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
        if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
        return num.toLocaleString();
    }

    static getStatusBadge(status) {
        const statuses = {
            running: '<span class="badge badge-success"><span class="status-dot running"></span>Online</span>',
            online: '<span class="badge badge-success"><span class="status-dot online"></span>Online</span>',
            stopped: '<span class="badge badge-info"><span class="status-dot stopped"></span>Stopped</span>',
            offline: '<span class="badge"><span class="status-dot offline"></span>Offline</span>',
            error: '<span class="badge badge-danger"><span class="status-dot error"></span>Error</span>',
            active: '<span class="badge badge-success">Active</span>',
            inactive: '<span class="badge">Inactive</span>',
        };
        return statuses[status] || `<span class="badge">${status}</span>`;
    }

    static escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    static debounce(func, wait) {
        let timeout;
        return function executedFunction(...args) {
            const later = () => {
                clearTimeout(timeout);
                func(...args);
            };
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
        };
    }
}

// Initialize global API instance
const api = new TGBotHubAPI();

/* =============================================
   TG BOT HUB - Auth Check & Dashboard Init
   ============================================= */

(function() {
    // Check authentication on page load
    const token = localStorage.getItem('tgbh_token');
    const userData = localStorage.getItem('tgbh_user');

    if (token && userData) {
        api.token = token;
        try {
            api.user = JSON.parse(userData);
        } catch (e) {
            api.user = null;
        }
    }

    // Redirect to login if not authenticated (for protected pages)
    const protectedPages = ['dashboard.html', 'admin.html'];
    const currentPage = window.location.pathname.split('/').pop();

    if (protectedPages.includes(currentPage)) {
        if (!api.isAuthenticated()) {
            window.location.href = '/login.html';
            return;
        }
    }

    // If on login/register page and already authenticated, redirect to dashboard
    if (['login.html', 'register.html'].includes(currentPage)) {
        if (api.isAuthenticated()) {
            window.location.href = '/dashboard.html';
            return;
        }
    }
})();

// =============================================
// THEME MANAGEMENT
// =============================================

const ThemeManager = {
    init() {
        const saved = localStorage.getItem('tgbh_theme') || 'dark';
        this.setTheme(saved);
    },

    setTheme(theme) {
        document.documentElement.setAttribute('data-theme', theme);
        localStorage.setItem('tgbh_theme', theme);

        document.querySelectorAll('.theme-toggle').forEach(btn => {
            btn.innerHTML = theme === 'dark' ? '🌙' : '☀️';
            btn.title = theme === 'dark' ? 'Switch to Light Mode' : 'Switch to Dark Mode';
        });
    },

    toggle() {
        const current = localStorage.getItem('tgbh_theme') || 'dark';
        this.setTheme(current === 'dark' ? 'light' : 'dark');
    }
};

// =============================================
// SIDEBAR MANAGEMENT
// =============================================

const SidebarManager = {
    init() {
        const toggle = document.querySelector('.mobile-menu-toggle');
        if (toggle) {
            toggle.addEventListener('click', () => {
                document.querySelector('.sidebar').classList.toggle('open');
            });
        }

        // Highlight active nav item
        const currentPage = window.location.pathname.split('/').pop();
        document.querySelectorAll('.nav-item').forEach(item => {
            const href = item.getAttribute('href');
            if (href && currentPage.includes(href.replace('.html', ''))) {
                item.classList.add('active');
            }
        });

        // Close sidebar on nav click (mobile)
        document.querySelectorAll('.nav-item').forEach(item => {
            item.addEventListener('click', () => {
                if (window.innerWidth <= 1024) {
                    document.querySelector('.sidebar').classList.remove('open');
                }
            });
        });
    },

    updateUser(user) {
        const avatarEl = document.querySelector('.sidebar-user-avatar');
        const nameEl = document.querySelector('.sidebar-user-name');
        const roleEl = document.querySelector('.sidebar-user-role');

        if (avatarEl) {
            avatarEl.textContent = (user.full_name || user.username).charAt(0).toUpperCase();
        }
        if (nameEl) {
            nameEl.textContent = user.full_name || user.username;
        }
        if (roleEl) {
            roleEl.textContent = user.role.charAt(0).toUpperCase() + user.role.slice(1);
        }

        // Show/hide admin nav items
        const adminItems = document.querySelectorAll('.nav-item.admin-only');
        adminItems.forEach(item => {
            item.style.display = (user.role === 'admin' || user.role === 'superadmin') ? 'flex' : 'none';
        });
    }
};

// =============================================
// DASHBOARD INITIALIZATION
// =============================================

document.addEventListener('DOMContentLoaded', function() {
    // Initialize theme
    ThemeManager.init();

    // Initialize sidebar
    SidebarManager.init();

    // Update user info if logged in
    if (api.isAuthenticated() && api.user) {
        SidebarManager.updateUser(api.user);
    }

    // Theme toggle listeners
    document.querySelectorAll('.theme-toggle').forEach(btn => {
        btn.addEventListener('click', ThemeManager.toggle);
    });

    // Logout buttons
    document.querySelectorAll('.logout-btn').forEach(btn => {
        btn.addEventListener('click', async (e) => {
            e.preventDefault();
            const confirmed = await UI.showConfirm('Are you sure you want to logout?', 'Logout');
            if (confirmed) {
                api.logout();
            }
        });
    });

    // Notification bell
    const notifBtn = document.querySelector('.notification-btn');
    if (notifBtn) {
        notifBtn.addEventListener('click', () => {
            UI.showToast('No new notifications', 'info');
        });
    }
});

